from pathlib import Path
p=Path(__file__).parent/'industrial.js'
s=p.read_text(encoding='utf-8')
s=s.replace('pipes:false,sprinklers:false','pipes:true,sprinklers:true')
s=s.replace('let rooms=[];','let flowParticles=[];\nfunction flowAlong(pts){const cumulative=[0];for(let i=1;i<pts.length;i++)cumulative.push(cumulative.at(-1)+pts[i].distanceTo(pts[i-1]));const total=cumulative.at(-1);for(let offset=0;offset<total;offset+=7){const mesh=new THREE.Mesh(new THREE.SphereGeometry(.16,6,6),new THREE.MeshBasicMaterial({color:0xffe4ad,depthTest:false}));mesh.renderOrder=20;routeGroup.add(mesh);flowParticles.push({mesh,pts,cumulative,total,offset})}}\nfunction animateFlow(t){if(!routeGroup.visible)return;for(const f of flowParticles){const distance=(t*.004+f.offset)%f.total;let i=1;while(i<f.cumulative.length-1&&f.cumulative[i]<distance)i++;f.mesh.position.lerpVectors(f.pts[i-1],f.pts[i],(distance-f.cumulative[i-1])/(f.cumulative[i]-f.cumulative[i-1]));}}\nlet rooms=[];')
s=s.replace("$('roomList').innerHTML=rooms.map", "$('roomList').innerHTML='<option value=\"\">구획실을 선택하세요</option>'+rooms.map")
s=s.replace("$('roomList').value='0'", "$('roomList').value=''")
s=s.replace('function drawRoutes(){dispose(routeGroup);const visible=state.currentRoutes.filter', 'function drawRoutes(){dispose(routeGroup);flowParticles=[];const visible=(state.currentRoutes||[]).filter')
s=s.replace('i===state.chosen?0xff4053:0xff949d','i===state.chosen?0xff861f:0xffb86b').replace('0xff4053','0xff861f')
s=s.replace('if(!pts)continue;let accumulated=4','if(!pts)continue;flowAlong(pts);let accumulated=4')
s=s.replace("function updateRoutes(){const r=", "function updateRoutes(){if($('roomList').value===''&&!state.fire){state.currentRoutes=[];dispose(destinationGroup);drawRoutes();$('routeHint').textContent='구획실을 선택하면 진입 경로가 표시됩니다.';return}const r=")
s=s.replace('function animate(){requestAnimationFrame(animate);renderer.render', 'function animate(t=0){requestAnimationFrame(animate);animateFlow(t);renderer.render')
s=s.replace('coverage,nodes,ready:true','coverage,nodes,animateFlow,get flowParticles(){return flowParticles},ready:true')
s=s.replace('))line(layers[f.n].pipes,', '))stroke(layers[f.n].pipes,').replace('0xed6570,true)','0xec3549,.09)')
s=s.replace('line(layers[1].pipes,','stroke(layers[1].pipes,')
